import React, { useRef, useEffect } from 'react';

const HtmlDialog = ({ onSubmit, defaultText }) => {
  const textRef = useRef(null);

  useEffect(() => {
    // Mettre le focus sur le champ de texte lorsque le composant est monté
    if (textRef.current) {
      textRef.current.focus();
    }
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const text = textRef.current.value;
    onSubmit(text);
  };

  return (
    <form onSubmit={handleSubmit}>
      <br />
      <div>
        <div
          style={{
            padding: '10px 20px',
            fontSize: '16px', //16
            backgroundColor: '#4CAF50',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            display: 'inline-block', // Pour s'assurer que le div prend la même taille qu'un bouton
            textAlign: 'center' // Pour centrer le texte
          }}
        >
          1. Complète le draft et, le cas échéant, inclus les informations manquantes [x]
        </div>
      </div>
      <br />
      <textarea
        ref={textRef}
        rows="15"
        cols="50" //avant 16.8. 50 cols
        
        
        defaultValue={defaultText}
      />
      <br /><br />
      <button
        type="submit"
        style={{
          padding: '10px 20px',
          fontSize: '16px',
          backgroundColor: '#4CAF50',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
      >
        2. Clique pour sélectionner les actions à déléguer aux IA (choisis 2 à 5 tâches par itération)
      </button>
    </form>
  );
};

export default HtmlDialog;

